cd /testbed && python3 - <<'PY'
import difflib
import pathlib
import subprocess
path = pathlib.Path('axum/src/routing/tests/fallback.rs')
old = path.read_text()
addition = '''
#[crate::test]
async fn serve_dir_in_fallback_router() {
    let routes_static = Router::new().nest_service(
        "/",
        get_service(tower_http::services::ServeDir::new(env!("CARGO_MANIFEST_DIR"))),
    );
    let app = Router::new().fallback_service(routes_static);

    let res = app
        .oneshot(Request::builder().uri("/README.md").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let body = hyper::body::to_bytes(res.into_body()).await.unwrap();
    assert_eq!(body.as_ref(), include_bytes!("../../../README.md"));
}

#[cfg(feature = "matched-path")]
#[crate::test]
async fn fallback_does_not_set_matched_path() {
    async fn fallback(path: Option<crate::extract::MatchedPath>) -> &'static str {
        assert!(path.is_none());
        "fallback"
    }

    let app = Router::new()
        .nest("/nested", Router::new().fallback(fallback))
        .fallback(fallback);
    let client = TestClient::new(app);

    for path in ["/", "/missing", "/nested", "/nested/", "/nested/missing"] {
        let res = client.get(path).send().await;
        assert_eq!(res.status(), StatusCode::OK);
        assert_eq!(res.text().await, "fallback");
    }
}

#[cfg(feature = "matched-path")]
#[crate::test]
async fn matched_path_in_fallback_router() {
    let inner = Router::new()
        .route("/", get(|path: crate::extract::MatchedPath| async move {
            path.as_str().to_owned()
        }))
        .route("/:name", get(|path: crate::extract::MatchedPath| async move {
            path.as_str().to_owned()
        }));
    let client = TestClient::new(Router::new().fallback_service(inner));

    assert_eq!(client.get("/").send().await.text().await, "/");
    assert_eq!(client.get("/foo").send().await.text().await, "/:name");
}
'''
new = old + addition
subprocess.run(['patch', '-p0'], input=''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile=str(path), tofile=str(path))), text=True, check=True)
